@dataclass(frozen=True)
class Node:
    kind: str
    value: object = None
    children: tuple["Node", ...] = ()

    def __repr__(self) -> str:
        if self.children:
            return f"Node({self.kind!r}, {self.value!r}, {self.children!r})"
        return f"Node({self.kind!r}, {self.value!r})"


_PREC = {",": 100, "//": 20, "=": 30, "|=": 30, "+=": 30, "-=": 30,
